import{_ as e,o as t,c as l,al as i}from"./chunks/framework.7vp1BMOE.js";const x=JSON.parse('{"title":"X-Plane 仿真","description":"","frontmatter":{},"headers":[],"relativePath":"zh/sim_xplane/index.md","filePath":"zh/sim_xplane/index.md"}'),n={name:"zh/sim_xplane/index.md"};function s(p,a,r,o,d,h){return t(),l("div",null,[...a[0]||(a[0]=[i(`<h1 id="x-plane-仿真" tabindex="-1">X-Plane 仿真 <a class="header-anchor" href="#x-plane-仿真" aria-label="Permalink to &quot;X-Plane 仿真&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>This simulator is <a href="./../simulation/community_supported_simulators">community supported and maintained</a>. It may or may not work with current versions of PX4 and may be removed in future releases. See <a href="./../dev_setup/dev_env">Toolchain Installation</a> for information about the environments and tools supported by the core development team.</p></div><p>[X-Plane] (<a href="https://www.x-plane.com/" target="_blank" rel="noreferrer">https://www.x-plane.com/</a>) 可通过社区支持的 [px4xplane] (<a href="https://github.com/alireza787b/px4xplane" target="_blank" rel="noreferrer">https://github.com/alireza787b/px4xplane</a>)桥接插件与 PX4 配合，用于软件在环 (SITL) 仿真(../simulation/index.md#sitl-simulation-environment)。 PX4 作为飞行控制器运行，而 X-Plane 提供机体动力学、可视场景和模拟传感器输入。 Px4xplane 桥接器是一个 X-Plane 插件：它在 X-Plane 内部运行，接受 PX4 的模拟 MAVLink 连接，将模拟传感器数据发布至 PX4，并将 PX4 执行器输出写入 X-Plane dataref。</p><h2 id="支持的载具" tabindex="-1">支持的载具 <a class="header-anchor" href="#支持的载具" aria-label="Permalink to &quot;支持的载具&quot;">​</a></h2><p>PX4 为以下机体提供 X-Plane SITL 机架配置：</p><table tabindex="0"><thead><tr><th>Vehicle</th><th>类型</th><th>PX4 构建目标</th></tr></thead><tbody><tr><td>Cessna 172</td><td>Plane</td><td><code>make px4_sitl_default xplane_cessna172</code></td></tr><tr><td>TB2</td><td>Plane</td><td><code>make px4_sitl_default xplane_tb2</code></td></tr><tr><td>Ehang 184</td><td>多旋翼</td><td><code>make px4_sitl_default xplane_ehang184</code></td></tr><tr><td>Alia-250</td><td>VTOL quadplane</td><td><code>make px4_sitl_default xplane_alia250</code></td></tr><tr><td>QuadTailsitter</td><td>VTOL tailsitter</td><td><code>make px4_sitl_default xplane_qtailsitter</code></td></tr></tbody></table><p>匹配的 X-Plane 飞机文件和桥接配置由 px4xplane 项目分发。 如果 PX4 具备支持 SITL 的相应控制路径，并且 px4xplane 能够将所需的执行器输出映射到可写的 X-Plane dataref，也可以集成其他 X-Plane 飞机或机体模型。</p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><ol><li><p>在将运行 PX4 SITL 的计算机、容器或 WSL2 环境中安装 <a href="./../dev_setup/dev_env">PX4 开发环境</a>。</p></li><li><p>安装 X-Plane 11 或 X-Plane 12。</p></li><li><p>从 <a href="https://github.com/alireza787b/px4xplane/releases" target="_blank" rel="noreferrer">px4xplane 发布页面</a>下载适用于当前操作系统的最新 px4xplane 发布包。</p></li><li><p>该发布包是压缩归档文件，而不是安装程序。 解压发布包，并将完整的 px4xplane 插件文件夹复制到：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">X-Plane/Resources/plugins/px4xplane</span></span></code></pre></div></li><li><p>将同一解压包中匹配的 X-Plane 飞机文件夹复制到 X-Plane 的飞机目录中。 除非发布说明另有要求，否则应将发布包中的 64/config.ini 与 px4xplane 插件放在一起。</p></li></ol><p><a href="https://github.com/alireza787b/px4xplane/blob/master/docs/BUILD.md#installation" target="_blank" rel="noreferrer">px4xplane 构建和安装指南</a>提供了有关插件文件夹结构的更多详细信息。</p><h2 id="网络设置" tabindex="-1">网络设置 <a class="header-anchor" href="#网络设置" aria-label="Permalink to &quot;网络设置&quot;">​</a></h2><p>PX4 通过 TCP 端口 4560 连接到 X-Plane 桥接器。 默认主机为 localhost，适用于 PX4 和 X-Plane 在同一台 Linux 或 macOS 计算机上运行的情况。</p><p>在 Windows 上，通常是在 Windows 中原生运行 X-Plane，并在 WSL2 中运行 PX4。 在这种情况下，启动 PX4 前，应在 WSL2 shell 中将 PX4_SIM_HOSTNAME 设置为 Windows 主机的 IP 地址。 该变量在 PX4/SITL 端设置，并指向运行 X-Plane 和 px4xplane 插件的主机：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PX4_SIM_HOSTNAME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> route</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> awk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;/default/ {print $3; exit}&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>然后从同一 shell 启动所需的 PX4 构建目标。 如果 PX4 在 Docker 或另一台计算机上运行，则应将 PX4_SIM_HOSTNAME 设置为 X-Plane 计算机可访问的 IP 地址或主机名。 确保 X-Plane 主机的防火墙允许 TCP 端口 4560 的入站连接。</p><h2 id="running-sitl" tabindex="-1">Running SITL <a class="header-anchor" href="#running-sitl" aria-label="Permalink to &quot;Running SITL&quot;">​</a></h2><ol><li><p>启动 X-Plane，并加载与 PX4 构建目标匹配的飞机。</p></li><li><p>确认 X-Plane 插件菜单中已加载 px4xplane 插件。</p></li><li><p>启动 PX4 SITL。 例如：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PX4-Autopilot</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl_default</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xplane_alia250</span></span></code></pre></div></li><li><p>像往常一样将 QGroundControl 连接到 PX4。</p></li></ol><p>桥接连接成功时，PX4 会输出 Simulator connected on TCP port 4560。</p><h2 id="自定义飞行器" tabindex="-1">自定义飞行器 <a class="header-anchor" href="#自定义飞行器" aria-label="Permalink to &quot;自定义飞行器&quot;">​</a></h2><p>如需添加其他 X-Plane 飞机：</p><ol><li>在 ROMFS/px4fmu_common/init.d-posix/airframes 中创建 PX4 机架配置文件。</li><li>在 src/modules/simulation/simulator_mavlink/sitl_targets_xplane.cmake 中添加匹配的 SITL 构建目标。</li><li>配置 px4xplane 桥接器，将 PX4 执行器输出映射到该飞机的 dataref。</li><li>根据 ULog 数据和 X-Plane 真值日志调优 PX4 参数。</li></ol><p>有关桥接器配置的详细信息，请参阅 px4xplane 自定义机架指南(<a href="https://github.com/alireza787b/px4xplane/blob/master/docs/custom-airframe-config.md" target="_blank" rel="noreferrer">https://github.com/alireza787b/px4xplane/blob/master/docs/custom-airframe-config.md</a>)。 有关 X-Plane 端的飞机设计和 dataref 映射，请参阅官方 Plane Maker 手册(<a href="https://developer.x-plane.com/manuals/planemaker/" target="_blank" rel="noreferrer">https://developer.x-plane.com/manuals/planemaker/</a>)和 X-Plane dataref 参考文档(<a href="https://developer.x-plane.com/datarefs/" target="_blank" rel="noreferrer">https://developer.x-plane.com/datarefs/</a>)。</p><h2 id="故障处理" tabindex="-1">故障处理 <a class="header-anchor" href="#故障处理" aria-label="Permalink to &quot;故障处理&quot;">​</a></h2><p>如果 PX4 一直等待仿真器，请确认 X-Plane 正在运行、px4xplane 插件已加载、PX4_SIM_HOSTNAME 指向 X-Plane 主机，并且 TCP 端口 4560 未被阻止。</p><p>如果飞机能够加载但无法正确响应，请确认 X-Plane 飞机、PX4 构建目标和 px4xplane 配置均对应同一机体。</p><p>如果出现估计器警告，请保持仿真器帧率稳定，确认已加载预期的机架参数，并在修改桥接器参数或机架参数之前检查 ULog 中的传感器和估计器主题。</p>`,26)])])}const k=e(n,[["render",s]]);export{x as __pageData,k as default};
